<script>
function pointsPage(){
    return {
        tab:'rewards', b:{}, hist:[],
        auth(){ try { return JSON.parse(localStorage.getItem('teatru_auth')||'null'); } catch(e){ return null; } },
        tierPct(){ if(!this.b.next_tier) return 100; const cur=this.b.tier_points||0, nxt=this.b.next_tier.min_points||1; return Math.min(100, Math.round(100*cur/nxt)); },
        async load(){
            const a=this.auth(); if(!a||!a.token) return;
            try { const r=await fetch('/api/proxy.php?action=gami-balance',{headers:{'Authorization':'Bearer '+a.token}}); const d=await r.json().catch(()=>({})); if(d&&d.enabled) this.b=d; } catch(e){}
            try { const r2=await fetch('/api/proxy.php?action=gami-history',{headers:{'Authorization':'Bearer '+a.token}}); const d2=await r2.json().catch(()=>({})); if(d2&&Array.isArray(d2.data)) this.hist=d2.data; } catch(e){}
        }
    };
}
</script>
